You are given a function,
int SumUniqueElements(int* arr, int length);
int SumUniqueElements(int* arr, int length);
static int SumUniqueElements(int[] arr){}
static int SumUniqueElements(int[] arr){}
def SumUniqueElements(arr):
The function accepts an integer array 'arr' of size 'length' as input. Implement the function such that
it returns the sum of unique (non-duplicate) elements in the array.
Note:
Return 0 if no unique element is found.
Computed values lie within integer range.

code.C:
#include <stdio.h>
#include <stdlib.h>
int cmp(const void *a, const void *b) { return (*(int*)a - *(int*)b); }
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int *arr = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    qsort(arr, n, sizeof(int), cmp);
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        int is_uniq = 1;
        if (i > 0 && arr[i] == arr[i-1]) is_uniq = 0;
        if (i < n - 1 && arr[i] == arr[i+1]) is_uniq = 0;
        if (is_uniq) sum += arr[i];
    }
    printf("%lld\n", sum);
    free(arr);
    return 0;
}

code.C++:
#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;
int main() {
    int n; if (cin >> n) {
        vector<int> a(n);
        unordered_map<int, int> cnt;
        for (int i = 0; i < n; i++) { cin >> a[i]; cnt[a[i]]++; }
        long long sum = 0;
        for (int x : a) if (cnt[x] == 1) sum += x;
        cout << sum << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
import java.util.HashMap;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            int[] a = new int[n];
            HashMap<Integer, Integer> cnt = new HashMap<>();
            for (int i = 0; i < n; i++) { a[i] = sc.nextInt(); cnt.put(a[i], cnt.getOrDefault(a[i], 0) + 1); }
            long sum = 0;
            for (int x : a) if (cnt.get(x) == 1) sum += x;
            System.out.println(sum);
        }
    }
}

